package dev.underthebedrock;
import dev.underthebedrock.command.*;import dev.underthebedrock.horror.*;import dev.underthebedrock.integration.IntegrationManager;import dev.underthebedrock.storage.PlayerLocationStore;import dev.underthebedrock.world.VoidWorldManager;import org.bukkit.command.PluginCommand;import org.bukkit.plugin.java.JavaPlugin;import java.util.Objects;
public final class UnderTheBedrockPlugin extends JavaPlugin {
 private VoidWorldManager worlds;private PlayerLocationStore locations;private IntegrationManager integrations;private OccurrenceDirector occurrences;private HorrorEntityController entities;private ClueManager clues;
 @Override public void onEnable(){saveDefaultConfig();integrations=new IntegrationManager(this);if(!integrations.initialize()){getServer().getPluginManager().disablePlugin(this);return;}locations=new PlayerLocationStore(this);worlds=new VoidWorldManager(this);PlayerHorrorMemoryStore memoryStore=new PlayerHorrorMemoryStore(this);occurrences=new OccurrenceDirector(this,worlds,memoryStore);entities=new HorrorEntityController(this,worlds,occurrences,integrations.betterModel());clues=new ClueManager(this,worlds,occurrences);
  if(getConfig().getBoolean("horror.director.enabled",true)){occurrences.start();if(getConfig().getBoolean("horror.entities.enabled",true))entities.start();if(getConfig().getBoolean("horror.clues.enabled",true))clues.start();}
  register("enter",new EnterCommand(worlds,locations));register("leave",new LeaveCommand(locations));register("underthebedrock",new UnderTheBedrockCommand(worlds,integrations));register("evidence",new EvidenceCommand(occurrences));
  if(getConfig().getBoolean("world.enabled-on-startup",false)&&!worlds.start())getLogger().severe("Could not initialize the configured horror world.");getLogger().info("Under The Bedrock enabled; horror director, evidence system, and entity controller initialized.");}
 @Override public void onDisable(){if(clues!=null)clues.stop();if(entities!=null)entities.stop();if(occurrences!=null)occurrences.stop();if(locations!=null)locations.flush();}
 public OccurrenceDirector getOccurrenceDirector(){return occurrences;}
 private void register(String name,org.bukkit.command.CommandExecutor executor){PluginCommand c=Objects.requireNonNull(getCommand(name),"Missing command: "+name);c.setExecutor(executor);if(executor instanceof org.bukkit.command.TabCompleter tabs)c.setTabCompleter(tabs);}
}